-- ConnectionCyber — M08: financeiro, tesouraria e bancário.
begin;
create table public.erp_financial_categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,code text not null,name text not null,direction text not null check(direction in('receivable','payable','both')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id));
create table public.erp_cost_centers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,code text not null,name text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id));
create table public.erp_financial_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid,code text not null,name text not null,kind text not null check(kind in('cash','bank','wallet','clearing','card_clearing','other')),currency_code text not null default 'BRL' check(currency_code~'^[A-Z]{3}$'),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict);
create table public.erp_financial_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid not null,party_id uuid,category_id uuid,cost_center_id uuid,code text not null,direction text not null check(direction in('receivable','payable')),status text not null default 'draft' check(status in('draft','open','partially_settled','settled','cancelled')),currency_code text not null default 'BRL' check(currency_code~'^[A-Z]{3}$'),principal_amount numeric(19,4) not null check(principal_amount>0),issue_date date not null,competence_date date,due_date date not null,source_type text,source_id uuid,idempotency_key text not null,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict,foreign key(tenant_id,party_id) references public.erp_parties(tenant_id,id) on delete restrict,foreign key(tenant_id,category_id) references public.erp_financial_categories(tenant_id,id) on delete restrict,foreign key(tenant_id,cost_center_id) references public.erp_cost_centers(tenant_id,id) on delete restrict);
create table public.erp_installments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,financial_entry_id uuid not null,number integer not null check(number>0),status text not null default 'open' check(status in('open','partially_settled','settled','overdue','cancelled')),due_date date not null,principal_amount numeric(19,4) not null check(principal_amount>0),interest_amount numeric(19,4) not null default 0 check(interest_amount>=0),fine_amount numeric(19,4) not null default 0 check(fine_amount>=0),discount_amount numeric(19,4) not null default 0 check(discount_amount>=0),created_at timestamptz not null default now(),unique(tenant_id,financial_entry_id,number),unique(tenant_id,id),foreign key(tenant_id,financial_entry_id) references public.erp_financial_entries(tenant_id,id) on delete restrict);
create table public.erp_settlements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,financial_account_id uuid not null,status text not null default 'pending' check(status in('pending','confirmed','reversed','failed')),direction text not null check(direction in('in','out')),currency_code text not null default 'BRL' check(currency_code~'^[A-Z]{3}$'),gross_amount numeric(19,4) not null check(gross_amount>0),fee_amount numeric(19,4) not null default 0 check(fee_amount>=0),discount_amount numeric(19,4) not null default 0 check(discount_amount>=0),net_amount numeric(19,4) not null check(net_amount>0),settled_at timestamptz,idempotency_key text not null,reversal_of_id uuid,external_reference text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,financial_account_id) references public.erp_financial_accounts(tenant_id,id) on delete restrict,foreign key(tenant_id,reversal_of_id) references public.erp_settlements(tenant_id,id) on delete restrict,check(net_amount=gross_amount-fee_amount-discount_amount),check((status='confirmed' and settled_at is not null) or status<>'confirmed'));
create table public.erp_settlement_allocations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,settlement_id uuid not null,installment_id uuid not null,principal_amount numeric(19,4) not null default 0 check(principal_amount>=0),interest_amount numeric(19,4) not null default 0 check(interest_amount>=0),fine_amount numeric(19,4) not null default 0 check(fine_amount>=0),discount_amount numeric(19,4) not null default 0 check(discount_amount>=0),allocated_amount numeric(19,4) not null check(allocated_amount>0),created_at timestamptz not null default now(),unique(tenant_id,settlement_id,installment_id),unique(tenant_id,id),foreign key(tenant_id,settlement_id) references public.erp_settlements(tenant_id,id) on delete restrict,foreign key(tenant_id,installment_id) references public.erp_installments(tenant_id,id) on delete restrict,check(allocated_amount=principal_amount+interest_amount+fine_amount-discount_amount));
create table public.erp_financial_movements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,financial_account_id uuid not null,type text not null check(type in('settlement','transfer','fee','adjustment','reversal')),direction text not null check(direction in('in','out')),amount numeric(19,4) not null check(amount>0),currency_code text not null default 'BRL' check(currency_code~'^[A-Z]{3}$'),settlement_id uuid,transfer_group_id uuid,source_type text,source_id uuid,idempotency_key text not null,occurred_at timestamptz not null default now(),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,financial_account_id) references public.erp_financial_accounts(tenant_id,id) on delete restrict,foreign key(tenant_id,settlement_id) references public.erp_settlements(tenant_id,id) on delete restrict);
create table public.erp_bank_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,financial_account_id uuid not null,bank_code text not null,branch_code text,account_masked text not null,account_type text not null check(account_type in('checking','savings','payment','investment','other')),holder_name text,secret_reference text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,financial_account_id),unique(tenant_id,id),foreign key(tenant_id,financial_account_id) references public.erp_financial_accounts(tenant_id,id) on delete restrict,check(secret_reference is null or secret_reference~'^[a-zA-Z0-9_./:-]{3,200}$'));
create table public.erp_bank_transactions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,bank_account_id uuid not null,external_id text,transaction_hash text not null check(transaction_hash~'^[a-f0-9]{64}$'),posted_on date not null,description text not null,amount numeric(19,4) not null check(amount<>0),currency_code text not null default 'BRL' check(currency_code~'^[A-Z]{3}$'),reference text,status text not null default 'unmatched' check(status in('unmatched','matched','split','ignored')),import_batch_key text not null,created_at timestamptz not null default now(),unique(tenant_id,bank_account_id,transaction_hash),unique nulls not distinct(tenant_id,bank_account_id,external_id),unique(tenant_id,id),foreign key(tenant_id,bank_account_id) references public.erp_bank_accounts(tenant_id,id) on delete restrict);
create table public.erp_bank_reconciliations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,bank_account_id uuid not null,period_from date not null,period_to date not null,status text not null default 'draft' check(status in('draft','processing','completed','cancelled')),opening_balance numeric(19,4) not null,closing_balance numeric(19,4) not null,completed_at timestamptz,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,bank_account_id) references public.erp_bank_accounts(tenant_id,id) on delete restrict,check(period_to>=period_from),check((status='completed' and completed_at is not null) or status<>'completed'));
create table public.erp_bank_reconciliation_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,reconciliation_id uuid not null,bank_transaction_id uuid not null,financial_movement_id uuid,matched_amount numeric(19,4) not null check(matched_amount<>0),confidence numeric(5,4) check(confidence is null or confidence between 0 and 1),match_method text not null check(match_method in('manual','automatic','split','ignored')),notes text,created_at timestamptz not null default now(),unique(tenant_id,reconciliation_id,bank_transaction_id,financial_movement_id),unique(tenant_id,id),foreign key(tenant_id,reconciliation_id) references public.erp_bank_reconciliations(tenant_id,id) on delete restrict,foreign key(tenant_id,bank_transaction_id) references public.erp_bank_transactions(tenant_id,id) on delete restrict,foreign key(tenant_id,financial_movement_id) references public.erp_financial_movements(tenant_id,id) on delete restrict);
create table public.erp_card_receivables(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,sale_payment_id uuid,financial_account_id uuid not null,provider text not null,external_id text not null,status text not null default 'scheduled' check(status in('scheduled','available','settled','anticipated','disputed','cancelled')),gross_amount numeric(19,4) not null check(gross_amount>0),fee_amount numeric(19,4) not null default 0 check(fee_amount>=0),net_amount numeric(19,4) not null check(net_amount>0),expected_on date not null,settled_on date,created_at timestamptz not null default now(),unique(tenant_id,provider,external_id),unique(tenant_id,id),foreign key(tenant_id,sale_payment_id) references public.erp_sale_payments(tenant_id,id) on delete restrict,foreign key(tenant_id,financial_account_id) references public.erp_financial_accounts(tenant_id,id) on delete restrict,check(net_amount=gross_amount-fee_amount));
create table public.erp_checks(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,direction text not null check(direction in('received','issued')),party_id uuid,bank_name text,check_number_masked text not null,status text not null check(status in('received','issued','held','deposited','cleared','returned','cancelled')),amount numeric(19,4) not null check(amount>0),due_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,direction,check_number_masked),unique(tenant_id,id),foreign key(tenant_id,party_id) references public.erp_parties(tenant_id,id) on delete restrict);
create table public.erp_billing_slips(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,installment_id uuid not null,provider text not null,external_id text not null,status text not null default 'draft' check(status in('draft','registered','pending','paid','overdue','cancelled','protested')),our_number_masked text,digitable_line_masked text,due_date date not null,amount numeric(19,4) not null check(amount>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,provider,external_id),unique(tenant_id,id),foreign key(tenant_id,installment_id) references public.erp_installments(tenant_id,id) on delete restrict);

insert into public.erp_permissions(key,name,description,category) values
('finance.read','Consultar financeiro','Consulta títulos, parcelas e movimentos.','Financeiro'),('finance.entry','Lançar títulos','Cria títulos e parcelas.','Financeiro'),('finance.settle','Liquidar títulos','Confirma recebimentos e pagamentos.','Financeiro'),('finance.reverse','Estornar liquidações','Cria contrapartidas financeiras.','Financeiro'),('finance.adjust','Ajustar financeiro','Registra ajustes auditados.','Financeiro'),('treasury.read','Consultar tesouraria','Consulta contas e saldos derivados.','Tesouraria'),('treasury.manage','Gerenciar tesouraria','Mantém contas financeiras.','Tesouraria'),('treasury.transfer','Transferir valores','Posta transferências balanceadas.','Tesouraria'),('banking.read','Consultar bancos','Consulta contas e extratos.','Bancário'),('banking.import','Importar extratos','Importa transações idempotentes.','Bancário'),('banking.reconcile','Conciliar bancos','Concilia extrato e livro.','Bancário'),('receivables.read','Consultar recebíveis','Consulta contas a receber.','Recebíveis'),('receivables.manage','Gerenciar recebíveis','Mantém recebíveis.','Recebíveis'),('payables.read','Consultar pagamentos','Consulta contas a pagar.','Pagamentos'),('payables.manage','Gerenciar pagamentos','Mantém contas a pagar.','Pagamentos') on conflict(key) do update set name=excluded.name,description=excluded.description,category=excluded.category,active=true;

create or replace function public.erp_post_financial_entry(p_tenant_id uuid,p_establishment_id uuid,p_party_id uuid,p_code text,p_direction text,p_amount numeric,p_issue_date date,p_due_dates date[],p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid;v_due date;v_n int:=0;v_count int;v_base numeric(19,4);v_last numeric(19,4); begin if not (erp_security.has_permission(p_tenant_id,'finance.entry') or public.is_platform_staff()) then raise exception 'permission denied';end if;select id into v_id from public.erp_financial_entries where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key;if v_id is not null then return v_id;end if;v_count:=coalesce(array_length(p_due_dates,1),0);if p_amount<=0 or v_count=0 then raise exception 'invalid amount/installments';end if;v_base:=trunc(p_amount/v_count,4);v_last:=p_amount-v_base*(v_count-1);insert into public.erp_financial_entries(tenant_id,establishment_id,party_id,code,direction,status,currency_code,principal_amount,issue_date,due_date,idempotency_key,created_by) values(p_tenant_id,p_establishment_id,p_party_id,p_code,p_direction,'open','BRL',p_amount,p_issue_date,p_due_dates[1],p_idempotency_key,auth.uid()) returning id into v_id;foreach v_due in array p_due_dates loop v_n:=v_n+1;insert into public.erp_installments(tenant_id,financial_entry_id,number,due_date,principal_amount) values(p_tenant_id,v_id,v_n,v_due,case when v_n=v_count then v_last else v_base end);end loop;return v_id;end $$;
create or replace function public.erp_confirm_settlement(p_tenant_id uuid,p_settlement_id uuid,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare v public.erp_settlements%rowtype;v_sum numeric(19,4);r record;v_paid numeric(19,4);v_due numeric(19,4); begin if not (erp_security.has_permission(p_tenant_id,'finance.settle') or public.is_platform_staff()) then raise exception 'permission denied';end if;select * into v from public.erp_settlements where tenant_id=p_tenant_id and id=p_settlement_id for update;if not found then raise exception 'settlement not found';end if;if v.status='confirmed' then return v.id;end if;if v.status<>'pending' or v.idempotency_key<>p_idempotency_key then raise exception 'invalid settlement';end if;select coalesce(sum(allocated_amount),0) into v_sum from public.erp_settlement_allocations where tenant_id=p_tenant_id and settlement_id=v.id;if v_sum<>v.net_amount then raise exception 'allocation mismatch';end if;for r in select a.installment_id,a.allocated_amount from public.erp_settlement_allocations a where a.tenant_id=p_tenant_id and a.settlement_id=v.id order by a.installment_id loop perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||r.installment_id::text,0));select i.principal_amount+i.interest_amount+i.fine_amount-i.discount_amount,coalesce(sum(a2.allocated_amount) filter(where s2.status='confirmed'),0) into v_due,v_paid from public.erp_installments i left join public.erp_settlement_allocations a2 on a2.tenant_id=i.tenant_id and a2.installment_id=i.id left join public.erp_settlements s2 on s2.tenant_id=a2.tenant_id and s2.id=a2.settlement_id where i.tenant_id=p_tenant_id and i.id=r.installment_id group by i.id;if v_paid+r.allocated_amount>v_due then raise exception 'over settlement';end if;end loop;update public.erp_settlements set status='confirmed',settled_at=now() where tenant_id=p_tenant_id and id=v.id;insert into public.erp_financial_movements(tenant_id,financial_account_id,type,direction,amount,currency_code,settlement_id,idempotency_key,created_by) values(p_tenant_id,v.financial_account_id,'settlement',v.direction,v.net_amount,v.currency_code,v.id,p_idempotency_key||':movement',auth.uid());return v.id;end $$;
create or replace function public.erp_transfer_financial_balance(p_tenant_id uuid,p_from_account_id uuid,p_to_account_id uuid,p_amount numeric,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_group uuid:=gen_random_uuid();begin if not (erp_security.has_permission(p_tenant_id,'treasury.transfer') or public.is_platform_staff()) then raise exception 'permission denied';end if;if p_from_account_id=p_to_account_id or p_amount<=0 then raise exception 'invalid transfer';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||least(p_from_account_id::text,p_to_account_id::text),0));perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||greatest(p_from_account_id::text,p_to_account_id::text),0));if exists(select 1 from public.erp_financial_movements where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key||':out') then select transfer_group_id into v_group from public.erp_financial_movements where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key||':out';return v_group;end if;insert into public.erp_financial_movements(tenant_id,financial_account_id,type,direction,amount,transfer_group_id,idempotency_key,created_by) values(p_tenant_id,p_from_account_id,'transfer','out',p_amount,v_group,p_idempotency_key||':out',auth.uid()),(p_tenant_id,p_to_account_id,'transfer','in',p_amount,v_group,p_idempotency_key||':in',auth.uid());return v_group;end $$;

do $$ declare t text;begin foreach t in array array['erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_financial_entries','erp_installments','erp_settlements','erp_settlement_allocations','erp_financial_movements','erp_bank_accounts','erp_bank_transactions','erp_bank_reconciliations','erp_bank_reconciliation_items','erp_card_receivables','erp_checks','erp_billing_slips'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select to authenticated using ((select erp_security.has_permission(tenant_id,''finance.read'')) or (select erp_security.has_permission(tenant_id,''treasury.read'')) or (select erp_security.has_permission(tenant_id,''banking.read'')) or (select erp_security.has_permission(tenant_id,''receivables.read'')) or (select erp_security.has_permission(tenant_id,''payables.read'')) or (select public.is_platform_staff()))',t||'_select',t);end loop;end $$;
do $$ declare t text;begin foreach t in array array['erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_settlements','erp_settlement_allocations','erp_bank_accounts','erp_bank_transactions','erp_bank_reconciliations','erp_bank_reconciliation_items','erp_card_receivables','erp_checks','erp_billing_slips'] loop execute format('create policy %I on public.%I for insert to authenticated with check ((select erp_security.has_permission(tenant_id,''finance.settle'')) or (select erp_security.has_permission(tenant_id,''treasury.manage'')) or (select erp_security.has_permission(tenant_id,''banking.import'')) or (select erp_security.has_permission(tenant_id,''banking.reconcile'')) or (select public.is_platform_staff()))',t||'_insert',t);end loop;end $$;
do $$ declare t text;begin foreach t in array array['erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_bank_accounts','erp_checks','erp_billing_slips'] loop execute format('create policy %I on public.%I for update to authenticated using ((select erp_security.has_permission(tenant_id,''finance.adjust'')) or (select erp_security.has_permission(tenant_id,''treasury.manage'')) or (select erp_security.has_permission(tenant_id,''banking.reconcile'')) or (select public.is_platform_staff())) with check ((select erp_security.has_permission(tenant_id,''finance.adjust'')) or (select erp_security.has_permission(tenant_id,''treasury.manage'')) or (select erp_security.has_permission(tenant_id,''banking.reconcile'')) or (select public.is_platform_staff()))',t||'_update',t);end loop;end $$;
do $$ declare t text;begin foreach t in array array['erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_financial_entries','erp_installments','erp_settlements','erp_settlement_allocations','erp_financial_movements','erp_bank_accounts','erp_bank_transactions','erp_bank_reconciliations','erp_bank_reconciliation_items','erp_card_receivables','erp_checks','erp_billing_slips'] loop execute format('revoke all on table public.%I from anon,authenticated',t);if t in('erp_financial_entries','erp_installments','erp_financial_movements') then execute format('grant select on table public.%I to authenticated',t);elsif t in('erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_bank_accounts','erp_checks','erp_billing_slips') then execute format('grant select,insert,update on table public.%I to authenticated',t);else execute format('grant select,insert on table public.%I to authenticated',t);end if;execute format('grant all on table public.%I to service_role',t);end loop;end $$;
revoke execute on function public.erp_post_financial_entry(uuid,uuid,uuid,text,text,numeric,date,date[],text),public.erp_confirm_settlement(uuid,uuid,text),public.erp_transfer_financial_balance(uuid,uuid,uuid,numeric,text) from public,anon;
grant execute on function public.erp_post_financial_entry(uuid,uuid,uuid,text,text,numeric,date,date[],text),public.erp_confirm_settlement(uuid,uuid,text),public.erp_transfer_financial_balance(uuid,uuid,uuid,numeric,text) to authenticated,service_role;
commit;
